-- 2. Invoices and their lines

-- HVI2614 - Black Groundbreaker Flannel.xls
INSERT INTO dtc_invoices (manufacturer, invoice_number, doc_type, invoice_date, currency, total_amount, deposit_paid, overpaid_amount, balance_due, deposits, refs, file_name, file_hash, extraction_method, warnings, created_by)
VALUES ('bing-bing', 'HVI2614', 'proforma', '2026-06-08', 'USD', 3778.85, NULL, NULL, NULL,
  '[]'::jsonb, ARRAY['HVI2614']::text[], 'HVI2614 - Black Groundbreaker Flannel.xls', '326685816223969d5f187310e2ff658e2ffcb17049b603d81d70f24ddb825728', 'history', '[]'::jsonb, 'history load')
ON CONFLICT (manufacturer, invoice_number, doc_type) DO NOTHING;
INSERT INTO dtc_invoice_lines (invoice_id, position, description, line_type, quantity, unit_price, amount, packed_quantity, dtc_product_id, allocation, split_of, note)
SELECT inv.id, v.position, v.description, v.line_type, v.quantity, v.unit_price, v.amount, v.packed_quantity, v.pid, v.allocation, v.split_of, v.note
FROM (SELECT id FROM dtc_invoices WHERE manufacturer = 'bing-bing' AND invoice_number = 'HVI2614' AND doc_type = 'proforma') inv
CROSS JOIN (VALUES
  (0, 'Flannel Shirt', 'product', 313::numeric, 11.45::numeric, 3583.85::numeric, NULL::numeric, (SELECT id FROM dtc_products WHERE name = 'Flannel - Black/Yellow OG' LIMIT 1), 'dtc', NULL::integer, NULL),
  (1, 'photography', 'photography', NULL::numeric, 45::numeric, 45::numeric, NULL::numeric, (SELECT id FROM dtc_products WHERE name = 'Flannel - Black/Yellow OG' LIMIT 1), 'dtc', 1::integer, '1-way split of 45 using goods value.'),
  (2, 'snap button mode fee', 'fee', NULL::numeric, NULL::numeric, 150::numeric, NULL::numeric, (SELECT id FROM dtc_products WHERE name = 'Flannel - Black/Yellow OG' LIMIT 1), 'dtc', 2::integer, '1-way split of 150 using goods value.')
) AS v(position, description, line_type, quantity, unit_price, amount, packed_quantity, pid, allocation, split_of, note)
WHERE NOT EXISTS (SELECT 1 FROM dtc_invoice_lines l WHERE l.invoice_id = inv.id);

