SELECT i.invoice_number, i.doc_type, i.invoice_date, i.total_amount, count(l.*) AS lines, round(sum(l.amount) FILTER (WHERE l.allocation = 'dtc'), 2) AS dtc_amount, round(sum(l.amount) FILTER (WHERE l.allocation = 'b2b'), 2) AS b2b_amount
FROM dtc_invoices i LEFT JOIN dtc_invoice_lines l ON l.invoice_id = i.id GROUP BY i.id ORDER BY i.invoice_date, i.doc_type;
